function output = heartlib(A)
% output = heartlib(A)
%
%    D_ii = sum_j A_ij
%            where
%            A: ℝ^(n × n)
%            
    n = size(A, 2);
    assert( isequal(size(A), [n, n]) );

    Dii_0 = zeros(2,0);
    Dvals_0 = zeros(1,0);
    for i = 1:n
        sum_0 = 0;
        for j = 1:size(A,2)
            sum_0 = sum_0 + A(i, j);
        end
        Dii_0(1:2,end+1) = [i;i];
        Dvals_0(end+1) = sum_0;
    end
    D = sparse(Dii_0(1,:),Dii_0(2,:),Dvals_0,n,n);
    output.D = D;
end

